"""Synthetic data station: a failure-driven curriculum, generated by batch inference.

What gets mutated is the closed-loop part. ``champion[D]`` (the model day D
starts from) carries ``hard_tasks.parquet``: the training tasks its own GRPO
rollouts kept failing. Day D mutates THOSE first, and only tops up with random
seed tasks — so yesterday's weaknesses become today's practice. The failures it
sometimes solved (the learnable frontier) are also replayed as-is. On the first
day the champion is the base model, has no failures on record, and the seeds
are random.

AceCoder-style recipe: prompt an instruct model to *mutate* seed problems
(new constraints, edge cases, renamed domain), parse out
question/solution/tests, then let the sandbox act as the oracle — only
samples whose generated reference solution passes their own generated tests
survive. Garbage generations are filtered by execution, not by a judge model.

Batching: many per-seed coroutines submit prompts to a
``flyte.extras.DynamicBatcher`` whose process_fn runs batched HF generation
on the GPU — the POC-scale version of the factory's "batch inference soaks
the idle GPU" pattern.
"""

from __future__ import annotations

import asyncio
import hashlib
import os
import re

import flyte
import flyte.io
import flyte.report
from flyte.extras import DynamicBatcher

import pandas as pd

from ..config import get_profile
from ..contracts import DATASET_COLUMNS, HARD_TASKS_FILE, find_leaks
from ..shared import reporting
from ..shared.rewards import count_test_functions
from ..shared.sandbox import run_solution_against_tests
from .envs import de_gpu_env

_MUTATION_PROMPT = """You are generating a NEW Python programming exercise by mutating the one below. Change the problem meaningfully (different domain, constraint, or edge cases) but keep it self-contained and testable.

Original problem:
{question}

Original solution signature: {declaration}

Respond in EXACTLY this format:

QUESTION:
<one-paragraph problem statement>

SOLUTION:
```python
<complete reference solution>
```

TESTS:
```python
from solution import <function_name>

<at least {min_tests} pytest test functions named test_*, using assert>
```
"""

#: Mutations sampled per seed. A 1.5B teacher passes its own tests ~1 time in 8,
#: so two draws per seed roughly doubles the day's curriculum for ~2 min of GPU.
SAMPLES_PER_SEED = 2

_CODE_BLOCKS = re.compile(r"```(?:python|py)?\s*\n(.*?)```", re.DOTALL)
#: A section header as small models actually write it: `QUESTION:`, `### QUESTION:`,
#: `**Tests:**` ... — any case, optional markdown, colon required.
_HEADER = re.compile(r"(?im)^[#>*\s]*(question|solution|tests)[*\s]*:[*]*[ \t]*")


def parse_generation(text: str) -> dict | None:
    """Extract {question, solution, tests} from the requested response format.

    Section-based, and tolerant of the ways a 1.5B teacher drifts from the
    format (markdown headers, prose after a block). Tests that call the
    function without importing it get ``from solution import *`` prepended —
    the sandbox runs them as `test_solution.py` next to `solution.py`.
    Anything else wrong (a bad solution, failing tests) is left for the
    execution oracle to reject.
    """
    heads = list(_HEADER.finditer(text))
    sections: dict[str, str] = {}
    for i, m in enumerate(heads):
        name = m.group(1).lower()
        end = heads[i + 1].start() if i + 1 < len(heads) else len(text)
        sections.setdefault(name, text[m.end() : end])
    if not {"question", "solution", "tests"} <= set(sections):
        return None
    question = sections["question"].strip()
    sol_blocks = _CODE_BLOCKS.findall(sections["solution"])
    test_blocks = _CODE_BLOCKS.findall(sections["tests"])
    if not (question and sol_blocks and test_blocks):
        return None
    solution, tests = sol_blocks[0].strip(), test_blocks[0].strip()
    if not (solution and tests):
        return None
    return {"question": question, "solution": solution, "tests": normalize_tests(tests)}


def normalize_tests(tests: str) -> str:
    """Make a generated test block runnable by pytest without changing what it checks.

    - no import of the solution -> ``from solution import *``
    - bare module-level asserts and no ``test_*`` function -> wrapped in one
    """
    if count_test_functions(tests) == 0 and re.search(r"(?m)^assert\b", tests):
        imports = [ln for ln in tests.splitlines() if re.match(r"(from|import)\s", ln)]
        body = [ln for ln in tests.splitlines() if not re.match(r"(from|import)\s", ln)]
        tests = "\n".join(imports) + "\n\n\ndef test_generated():\n" + "\n".join(
            ("    " + ln) if ln.strip() else "" for ln in body
        )
    if "from solution import" not in tests and "import solution" not in tests:
        tests = "from solution import *\n\n" + tests
    return tests


@flyte.trace
async def _generate_batch(model_name: str, prompts: list[str], max_new_tokens: int) -> list[str]:
    """One batched GPU generation call (traced: replayed on task retry)."""
    import torch
    from transformers import AutoModelForCausalLM, AutoTokenizer

    # Module-level cache so the model loads once per container.
    global _MODEL, _TOK  # noqa: PLW0603
    if "_MODEL" not in globals():
        _TOK = AutoTokenizer.from_pretrained(model_name)
        _MODEL = AutoModelForCausalLM.from_pretrained(
            model_name,
            torch_dtype=torch.bfloat16,
            device_map="cuda" if torch.cuda.is_available() else "cpu",
        )
    chats = [
        _TOK.apply_chat_template(
            [{"role": "user", "content": p}],
            tokenize=False,
            add_generation_prompt=True,
        )
        for p in prompts
    ]
    inputs = _TOK(chats, return_tensors="pt", padding=True, truncation=True, max_length=2048).to(_MODEL.device)
    with torch.no_grad():
        out = _MODEL.generate(
            **inputs,
            max_new_tokens=max_new_tokens,
            do_sample=True,
            temperature=0.9,
            top_p=0.95,
            pad_token_id=_TOK.pad_token_id or _TOK.eos_token_id,
        )
    gen = out[:, inputs["input_ids"].shape[1]:]
    return _TOK.batch_decode(gen, skip_special_tokens=True)


def pick_seeds(hard: pd.DataFrame | None, pool: pd.DataFrame, n: int, seed: int = 11) -> pd.DataFrame:
    """The day's mutation seeds: the champion's failures first, random fill after.

    Adds an ``origin`` column ("champion-failure" | "random") so the report and
    the dataset can show how much of the curriculum came from the loop.
    """
    picked = []
    if hard is not None and len(hard):
        h = hard.head(n).copy()
        h["origin"] = "champion-failure"
        picked.append(h)
    taken = sum(len(p) for p in picked)
    if taken < n and len(pool):
        used = set(picked[0]["question"]) if picked else set()
        rest = pool[~pool["question"].isin(used)]
        r = rest.sample(min(n - taken, len(rest)), random_state=seed).copy()
        r["origin"] = "random"
        picked.append(r)
    if not picked:
        return pool.head(0).assign(origin=[])
    return pd.concat(picked, ignore_index=True)


def frontier_replay(hard: pd.DataFrame | None, n: int) -> pd.DataFrame:
    """The champion's *learnable* failures, replayed as-is: rollout pass rate in (0, 0.5].

    A task the policy never solved gives GRPO no passing rollout to learn from;
    one it sometimes solves is exactly where the update has signal. They are
    train tasks from an earlier day, never held-out ones.
    """
    if hard is None or "rollout_pass_rate" not in hard or not len(hard):
        return pd.DataFrame(columns=DATASET_COLUMNS)
    f = hard[hard["rollout_pass_rate"] > 0].sort_values("rollout_pass_rate", ascending=False, kind="stable")
    f = f.head(n)[DATASET_COLUMNS].copy()
    f["source"] = "replay"
    f["difficulty"] = "replay:" + f["difficulty"].astype(str)
    return f.reset_index(drop=True)


@de_gpu_env.task(report=True)
async def generate_synthetic_tasks(
    dataset: flyte.io.File,
    champion: flyte.io.Dir,
    heldout: flyte.io.File,
    profile_name: str = "daily",
) -> flyte.io.File:
    """Generate oracle-verified synthetic tasks, seeded by the champion's failures.

    Returns a plain File: the factory build that wraps this task declares and
    publishes the `synthetic-tasks` artifact (see model_factory/factory.py).
    """
    profile = get_profile(profile_name)
    df = pd.read_parquet(await dataset.download())
    champ_dir = await champion.download()
    hard_path = os.path.join(champ_dir, HARD_TASKS_FILE)
    hard = pd.read_parquet(hard_path) if os.path.exists(hard_path) else None
    seeds = pick_seeds(hard, df[df["split"] == "train"], profile.synthetic_seeds)
    held = pd.read_parquet(await heldout.download())

    batcher = DynamicBatcher(
        process_fn=lambda prompts: _generate_batch(
            profile.synthetic_model, list(prompts), profile.synthetic_max_new_tokens
        ),
        max_batch_size=16,
        batch_timeout_s=0.5,
    )
    await batcher.start()

    async def one(seed) -> dict | None:
        prompt = _MUTATION_PROMPT.format(
            question=seed.question[:1500],
            declaration=seed.function_declaration or "any function",
            min_tests=max(3, profile.min_test_functions),
        )
        # submit() returns a future that resolves when its batch is processed
        future = await batcher.submit(prompt)
        text = await future
        parsed = parse_generation(text)
        if not parsed:
            return None
        if count_test_functions(parsed["tests"]) < 1:
            return None
        # Execution as the oracle: generated solution must pass generated tests.
        result = await asyncio.to_thread(
            run_solution_against_tests, parsed["solution"], parsed["tests"]
        )
        if not result.passed:
            return None
        qid = hashlib.sha1(parsed["question"].encode()).hexdigest()[:12]
        return {
            "task_id": f"syn_{qid}",
            "question": parsed["question"],
            "function_declaration": "",
            "tests": parsed["tests"],
            "reference_solution": parsed["solution"],
            "difficulty": f"synthetic:{seed.origin}",
            "n_tests": count_test_functions(parsed["tests"]),
            "source": "synthetic",
            "split": "train",
        }

    attempts = [s for s in seeds.itertuples() for _ in range(SAMPLES_PER_SEED)]
    results = await asyncio.gather(*(one(s) for s in attempts))
    await batcher.stop()
    kept = list({r["task_id"]: r for r in results if r}.values())  # dedup identical mutations
    # A mutation that reproduces a held-out problem verbatim is dropped here;
    # assemble_dataset re-checks the whole release.
    leaked = set(find_leaks([k["question"] for k in kept], held["question"]))
    kept = [k for i, k in enumerate(kept) if i not in leaked]

    replay = frontier_replay(hard, profile.synthetic_seeds)
    replay = replay.drop(index=find_leaks(replay["question"], held["question"])).reset_index(drop=True)
    out_df = pd.concat([pd.DataFrame(kept, columns=DATASET_COLUMNS), replay], ignore_index=True)
    out = "/tmp/synthetic_tasks.parquet"
    out_df.to_parquet(out, index=False)

    n_fail = int((seeds["origin"] == "champion-failure").sum()) if len(seeds) else 0
    body = reporting.stats_row(
        {
            "seeds mutated": f"{len(seeds)} x {SAMPLES_PER_SEED}",
            "from champion failures": n_fail,
            "random seeds": len(seeds) - n_fail,
            "parsed + oracle-verified": len(kept) + len(leaked),
            "dropped (held-out match)": len(leaked),
            "kept": len(kept),
            "replayed frontier tasks": len(replay),
            "yield": f"{len(kept) / max(len(attempts), 1):.0%}",
            "teacher": profile.synthetic_model.split("/")[-1],
        }
    )
    if kept:
        body += "<h3>Verified synthetic samples</h3>"
        body += reporting.table(
            ["task_id", "seeded from", "n_tests", "question", "solution (head)"],
            [[k["task_id"], k["difficulty"].split(":")[-1], k["n_tests"], k["question"][:250], k["reference_solution"][:250]] for k in kept[:10]],
        )
    await flyte.report.replace.aio(
        reporting.page("Synthetic tasks (failure-driven curriculum)", body)
    )
    await flyte.report.flush.aio()

    return await flyte.io.File.from_local(out)
